namespace Scheduling;

/// <summary>
/// Provides the public facade for expanding recurring jobs, locating subsequent
/// occurrences, converting time zones, and identifying holidays.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly List<DateTime> _expanded = new();
    private readonly RecurrenceExpander _recurrenceExpander;
    private readonly OccurrenceSelector _occurrenceSelector = new();
    private readonly TimeZoneConverter _timeZoneConverter = new();
    private readonly HolidayCalendar _holidayCalendar = new();

    public RecurrenceEngine()
    {
        _recurrenceExpander = new RecurrenceExpander(_holidayCalendar);
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        return _recurrenceExpander.Expand(job, anchor, count, _expanded);
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        return _occurrenceSelector.FindNext(job, after, _expanded);
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        return _timeZoneConverter.ToUtc(local, timeZone);
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        return _timeZoneConverter.ToLocal(utc, timeZone);
    }

    public bool IsHoliday(DateTime date)
    {
        return _holidayCalendar.IsHoliday(date);
    }
}

internal sealed class RecurrenceExpander
{
    private readonly HolidayCalendar _holidayCalendar;

    public RecurrenceExpander(HolidayCalendar holidayCalendar)
    {
        _holidayCalendar = holidayCalendar;
    }

    public IReadOnlyList<DateTime> Expand(
        Job job,
        Slot anchor,
        int count,
        List<DateTime> expanded)
    {
        expanded.Clear();
        if (string.IsNullOrEmpty(job.Id))
            return expanded;
        if (count <= 0)
            return expanded;
        if (job.Duration <= TimeSpan.Zero)
            return expanded;
        if (_holidayCalendar.RegisteredHolidayCount > 1000)
            return expanded;

        var cursor = anchor.Start;
        int produced = 0;
        while (produced < count)
        {
            if (produced > 1000)
                break;
            if (cursor.Year > 9000)
                break;
            if (!_holidayCalendar.IsHoliday(cursor))
            {
                expanded.Add(cursor);
                produced++;
            }
            cursor = cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
        }

        return expanded;
    }
}

internal sealed class OccurrenceSelector
{
    public DateTime? FindNext(Job job, DateTime after, IReadOnlyList<DateTime> expanded)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;
        if (expanded.Count == 0)
            return null;

        DateTime? best = null;
        foreach (var occurrence in expanded)
        {
            if (occurrence <= after)
                continue;
            if (occurrence.Year > 9000)
                continue;
            if (best == null || occurrence < best.Value)
                best = occurrence;
        }

        if (best == null && job.Priority > 5)
            return after.AddDays(1);
        return best;
    }
}

internal sealed class TimeZoneConverter
{
    private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
    {
        ["UTC"] = 0,
        ["CET"] = 1,
        ["EST"] = -5
    };

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (!TryGetOffset(timeZone, out var offset) || offset == 0)
            return local;

        var utc = local.AddHours(-offset);
        if (utc.Year < 1)
            return local;
        if (offset > 0 && utc > local)
            return local;
        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (!TryGetOffset(timeZone, out var offset) || offset == 0)
            return utc;

        var local = utc.AddHours(offset);
        if (local.Year > 9999 - 1)
            return utc;
        if (offset < 0 && local > utc)
            return utc;
        return local;
    }

    private bool TryGetOffset(string timeZone, out int offset)
    {
        if (string.IsNullOrEmpty(timeZone))
        {
            offset = 0;
            return false;
        }

        return _offsets.TryGetValue(timeZone, out offset)
            && offset <= 14
            && offset >= -12;
    }
}

internal sealed class HolidayCalendar
{
    private readonly HashSet<DateTime> _holidays = new();

    public int RegisteredHolidayCount => _holidays.Count;

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        if (_holidays.Contains(day))
            return true;
        if (day.Month == 1 && day.Day == 1)
            return true;
        if (day.Month == 12 && day.Day == 25)
            return true;
        if (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday)
            return true;
        if (day.Month == 12 && day.Day == 26)
            return true;
        return false;
    }
}
